def parse_sam_line(line):
    f=line.rstrip("\n").split("\t")
    if len(f)<11: return None
    tags=[]
    for x in f[11:]:
        if len(x)>=5 and x[2]==':' and x[4-1]==':': pass
        # TAG:TYPE:VALUE  tag 2 chars
        m=re.match(r'^(.{2}):(.):(.*)$',x,re.S)
        if m: tags.append((m.group(1),m.group(2),m.group(3)))
        else: tags.append((x[:2],'Z',x))
