        if line.startswith("@SQ"):
            d={}
            for p in line.split("\t")[1:]:
                if ":" in p:
                    k,v=p.split(":",1); d[k]=v
            if "SN" in d: out.append((d["SN"], int(d.get("LN",0))))
    return out
def sq_dict(header): return dict(sq_list(header))
def add_pg(header, argv, no_pg=False, vn=True):
