        if line.startswith("@PG"):
            for p in line.split("\t"):
                if p.startswith("ID:"): ids.append(p[3:]); last_pg_id=p[3:]
    newid="samtools"
    if newid in ids:
        i=1
        while f"samtools.{i}" in ids: i+=1
        newid=f"samtools.{i}"
    cl=" ".join(argv)
