# BAM
SEQ_CODES="=ACMGRSVTWYHKDBN"
SEQ_MAP={c:i for i,c in enumerate(SEQ_CODES)}
def reg2bin(beg,end):
    end-=1
    if beg>>14 == end>>14: return ((1<<15)-1)//7 + (beg>>14)
    if beg>>17 == end>>17: return ((1<<12)-1)//7 + (beg>>17)
    if beg>>20 == end>>20: return ((1<<9)-1)//7 + (beg>>20)
    if beg>>23 == end>>23: return ((1<<6)-1)//7 + (beg>>23)
    if beg>>26 == end>>26: return ((1<<3)-1)//7 + (beg>>26)
    return 0

BGZF_EOF=bytes.fromhex('1f8b08040000000000ff0600424302001b0003000000000000000000')
def bgzf_block(data, level=6):
    # compress data (<= 65000)
    comp=zlib.compressobj(level, zlib.DEFLATED, -15)
    cdata=comp.compress(data)+comp.flush()
    crc=zlib.crc32(data) & 0xffffffff
    bsize=18+len(cdata)+8-1
    hdr=struct.pack("<BBBBIBBH",0x1f,0x8b,8,4,0,0,0xff,6)
    # Actually gzip header: ID1 ID2 CM FLG MTIME(4) XFL OS, XLEN(2)
    hdr= b'\x1f\x8b\x08\x04\x00\x00\x00\x00\x00\xff\x06\x00BC' + struct.pack("<H", bsize)
    return hdr + cdata + struct.pack("<II", crc, len(data) & 0xffffffff)
def bgzf_write(out_fh, data_bytes, level=6, uncompressed=False):
    if uncompressed:
        # still BGZF blocks but level 0
        level=0
    for i in range(0, len(data_bytes), 65280):
        chunk=data_bytes[i:i+65280]
        out_fh.write(bgzf_block(chunk, level))
    if len(data_bytes)==0:
        out_fh.write(bgzf_block(b'', level))
    out_fh.write(BGZF_EOF)

def decode_bam(data, header_out=None):
    # data decompressed BAM bytes
    if not data.startswith(b'BAM\x01'): raise ValueError("not BAM")
    off=4
    l_text,=struct.unpack_from("<i",data,off); off+=4
    text=data[off:off+l_text].decode('utf-8',errors='replace'); off+=l_text
    header=[l for l in text.split("\n") if l]
    n_ref,=struct.unpack_from("<i",data,off); off+=4
    refs=[]
    for _ in range(n_ref):
        l_name,=struct.unpack_from("<i",data,off); off+=4
        name=data[off:off+l_name-1].decode(); off+=l_name
        l_ref,=struct.unpack_from("<i",data,off); off+=4
        refs.append((name,l_ref))
    records=[]
    while off < len(data):
        if off+4>len(data): break
        block_size,=struct.unpack_from("<i",data,off); off+=4
        rec_start=off
        refID,pos,l_read_name_mapq_bin,flag_nc,l_seq,next_refID,next_pos,tlen = struct.unpack_from("<iiIIIIIi",data,off)  # placeholder wrong
        # Correct layout: refID i, pos i, bin_mq_nl I, flag_nc I, l_seq i, next_refID i, next_pos i, tlen i  = 32 bytes
        refID,pos,bin_mq_nl,flag_nc,l_seq,next_refID,next_pos,tlen = struct.unpack_from("<iiIIiiii",data,off)
        mapq=(bin_mq_nl>>8)&0xff
        l_read_name=bin_mq_nl & 0xff
        flag=(flag_nc>>16)&0xffff
        n_cigar=flag_nc & 0xffff
        p=off+32
        qname=data[p:p+l_read_name-1].decode(); p+=l_read_name
        cigar_ops=[]
        for i in range(n_cigar):
            v,=struct.unpack_from("<I",data,p); p+=4
            cigar_ops.append((v>>4, CIGAR_OPS[v & 0xf]))
        cigar=cigar_str(cigar_ops) if cigar_ops else "*"
        seq_chars=[]
        for i in range(l_seq):
            byte=data[p + i//2]
            code = (byte>>4) if i%2==0 else (byte & 0xf)
            seq_chars.append(SEQ_CODES[code])
        p+= (l_seq+1)//2
        seq="".join(seq_chars) if l_seq else "*"
        if l_seq==0: seq="*"
        qual_bytes=data[p:p+l_seq]; p+=l_seq
        if l_seq==0: qual="*"
        elif all(b==0xff for b in qual_bytes): qual="*"
        else: qual="".join(chr(b+33) for b in qual_bytes)
        # aux
        tags=[]
        end=rec_start+block_size
        while p < end:
            tag=data[p:p+2].decode(); ty=chr(data[p+2]); p+=3
            if ty=='A': val=chr(data[p]); p+=1; tags.append((tag,ty,val))
            elif ty=='c': val=struct.unpack_from("<b",data,p)[0]; p+=1; tags.append((tag,'i',str(val)))
            elif ty=='C': val=struct.unpack_from("<B",data,p)[0]; p+=1; tags.append((tag,'i',str(val)))
            elif ty=='s': val=struct.unpack_from("<h",data,p)[0]; p+=2; tags.append((tag,'i',str(val)))
            elif ty=='S': val=struct.unpack_from("<H",data,p)[0]; p+=2; tags.append((tag,'i',str(val)))
            elif ty=='i': val=struct.unpack_from("<i",data,p)[0]; p+=4; tags.append((tag,'i',str(val)))
            elif ty=='I': val=struct.unpack_from("<I",data,p)[0]; p+=4; tags.append((tag,'i',str(val)))
            elif ty=='f': val=struct.unpack_from("<f",data,p)[0]; p+=4; tags.append((tag,'f',repr_float(val)))
            elif ty=='d': val=struct.unpack_from("<d",data,p)[0]; p+=8; tags.append((tag,'d',repr_float(val)))
            elif ty in 'ZH':
                e=data.find(b'\x00',p); val=data[p:e].decode(); p=e+1; tags.append((tag,ty,val))
            elif ty=='B':
                sub=chr(data[p]); ln,=struct.unpack_from("<i",data,p+1); p+=5
                fmt={'c':'b','C':'B','s':'h','S':'H','i':'i','I':'I','f':'f'}[sub]
                sz=struct.calcsize(fmt)
                vals=[struct.unpack_from("<"+fmt,data,p+i*sz)[0] for i in range(ln)]; p+=ln*sz
                if sub=='f': vals=[repr_float(v) for v in vals]
                tags.append((tag,'B',sub+","+",".join(str(v) for v in vals)))
            else: break
        off=rec_start+block_size
        rname=refs[refID][0] if refID>=0 else "*"
        rnext="*"
        if next_refID>=0:
            rnext="=" if next_refID==refID else refs[next_refID][0]
        rec=Rec(qname,flag,rname,pos+1 if refID>=0 else 0,mapq,cigar,rnext,next_pos+1 if next_refID>=0 else 0,tlen,seq,qual,tags)
        records.append(rec)
    return header, refs, records
def repr_float(v):
    # samtools prints floats %g ?
    return ('%g' % v)

def encode_bam(header, records):
    refs=sq_list(header)
    ref_index={n:i for i,(n,l) in enumerate(refs)}
    text=("\n".join(header)+"\n" if header else "").encode()
    out=bytearray()
    out+=b'BAM\x01'
    out+=struct.pack("<i",len(text)); out+=text
    out+=struct.pack("<i",len(refs))
    for n,l in refs:
        nb=n.encode()+b'\x00'
        out+=struct.pack("<i",len(nb)); out+=nb; out+=struct.pack("<i",l)
    for r in records:
        refID=ref_index.get(r.rname,-1) if r.rname!="*" else -1
        pos0=r.pos-1 if refID>=0 else -1
        if refID<0: pos0=-1
        ops=parse_cigar(r.cigar)
        if refID<0: ops=[]
        binv=0
        if refID>=0:
            end=pos0 + max(cigar_ref_len(ops),1)
            binv=reg2bin(pos0,end)
        qname_b=r.qname.encode()+b'\x00'
        l_seq=0 if r.seq=="*" else len(r.seq)
        bin_mq_nl=(binv<<16)|(r.mapq<<8)|len(qname_b)
        flag_nc=(r.flag<<16)|len(ops)
        if r.rnext=="=": next_refID=refID
        elif r.rnext=="*": next_refID=-1
        else: next_refID=ref_index.get(r.rnext,-1)
        next_pos=r.pnext-1 if next_refID>=0 and r.pnext>0 else -1
        if next_refID<0: next_pos=-1
        core=struct.pack("<iiIIiiii",refID,pos0,bin_mq_nl,flag_nc,l_seq,next_refID,next_pos,r.tlen)
        body=bytearray(core)
        body+=qname_b
        for ln,op in ops:
            body+=struct.pack("<I",(ln<<4)|CIGAR_OPS.index(op))
        # seq
        if l_seq:
            for i in range(0,l_seq,2):
                hi=SEQ_MAP.get(r.seq[i].upper(),0)
                lo=SEQ_MAP.get(r.seq[i+1].upper(),0) if i+1<l_seq else 0
                body.append((hi<<4)|lo)
            if r.qual=="*":
                body+=b'\xff'*l_seq
            else:
                for ch in r.qual[:l_seq]:
                    body.append(max(0,min(255,ord(ch)-33)))
                # pad if qual shorter
                if len(r.qual)<l_seq: body+=b'\xff'*(l_seq-len(r.qual))
        # aux
        for tag,ty,val in r.tags:
            body+=tag.encode(); body+=ty.encode() if ty!='B' else b'B'
            if ty=='A': body+=val.encode()[:1] if val else b'\x00'
            elif ty=='Z' or ty=='H': body+=val.encode()+b'\x00'
            elif ty=='i' or ty=='I':
                try: iv=int(val)
                except: iv=0
                # smallest fit like htslib? Use signed/unsigned choices
                if -128 <= iv <= 127: body[-1:]=b'c'; body+=struct.pack("<b",iv)
                elif 0 <= iv <= 255: body[-1:]=b'C'; body+=struct.pack("<B",iv)
                elif -32768 <= iv <= 32767: body[-1:]=b's'; body+=struct.pack("<h",iv)
                elif 0 <= iv <= 65535: body[-1:]=b'S'; body+=struct.pack("<H",iv)
                elif iv>=0: body[-1:]=b'I'; body+=struct.pack("<I",iv)
                else: body[-1:]=b'i'; body+=struct.pack("<i",iv)
            elif ty=='f': body+=struct.pack("<f",float(val))
            elif ty=='d': body+=struct.pack("<d",float(val))
            elif ty=='B':
                parts=val.split(",")
                sub=parts[0]; vals=parts[1:]
                body+=sub.encode()
                body+=struct.pack("<i",len(vals))
                fmt={'c':'b','C':'B','s':'h','S':'H','i':'i','I':'I','f':'f','d':'d'}[sub]
                for v in vals:
                    if sub in 'f d'.split(): body+=struct.pack("<"+fmt,float(v))
                    else: body+=struct.pack("<"+fmt,int(v))
            else:
                body+=val.encode()+b'\x00'
        out+=struct.pack("<i",len(body)); out+=body
    return bytes(out)

# Input reading
def read_raw_bytes(path):
    if path=="-" or path is None:
        return sys.stdin.buffer.read()
    with open(path,'rb') as f: return f.read()

def detect_and_read(path, need_records=True):
    # returns (header, records, fmt) fmt in SAM,BAM
    if path=="-" or path is None:
        data=sys.stdin.buffer.read()
        return parse_data_bytes(data, path)
    with open(path,'rb') as f: data=f.read()
    return parse_data_bytes(data, path)

def parse_data_bytes(data, path=""):
    if len(data)>=2 and data[0]==0x1f and data[1]==0x8b:
        try: dec=gzip.decompress(data)
        except Exception:
            # try zlib?
            dec=data
        if dec.startswith(b'BAM\x01'):
            header, refs, records = decode_bam(dec)
            # ensure header SQ match refs if header missing SQ? BAM header should have
            return header, records, "BAM"
        else:
            text=dec.decode('utf-8',errors='replace')
            return parse_sam_text(text)
    elif data.startswith(b'BAM\x01'):
        header, refs, records = decode_bam(data)
        return header, records, "BAM"
    elif data.startswith(b'CRAM'):
        raise ValueError("CRAM not supported")
    else:
        text=data.decode('utf-8',errors='replace')
        return parse_sam_text(text)

def parse_sam_text(text):
    header=[]; records=[]
    for line in text.splitlines():
        if not line: continue
        if line.startswith("@"): header.append(line)
        else:
            r=parse_sam_line(line)
            if r: records.append(r)
    return header, records, "SAM"

def open_input(path):
    # returns (header,records,fmt) with error handling similar to samtools
    try:
        return detect_and_read(path)
    except FileNotFoundError:
        eprint(f'[E::hts_open_format] Failed to open file "{path}" : No such file or directory')
        raise SystemExit(1)
    except Exception as ex:
        # generic
        raise

def read_fasta(path):
    # returns list of (name, seq, description line)
    seqs=[]; name=None; desc=""; buf=[]
    data=None
    if path=="-":
        text=sys.stdin.read()
    else:
        raw=open(path,'rb').read()
        if raw[:2]==b'\x1f\x8b': raw=gzip.decompress(raw)
        text=raw.decode()
    for line in text.splitlines():
        if line.startswith(">"):
            if name is not None: seqs.append((name, "".join(buf), desc))
            desc=line[1:]
            name=desc.split()[0] if desc.split() else ""
            buf=[]
        else: buf.append(line.strip())
    if name is not None: seqs.append((name, "".join(buf), desc))
    return seqs
def read_fastq(path):
    seqs=[]
    if path=="-": text=sys.stdin.read()
    else:
        raw=open(path,'rb').read()
        if raw[:2]==b'\x1f\x8b': raw=gzip.decompress(raw)
        text=raw.decode()
    lines=text.splitlines()
    i=0
    if lines and lines[0].startswith(">"):
        # fasta as fastq
        return read_fasta(path)
    while i < len(lines):
        if lines[i].startswith("@"):
            name=lines[i][1:].split()[0]; desc=lines[i][1:]
            seq_lines=[]; i+=1
            while i < len(lines) and not lines[i].startswith("+"):
                seq_lines.append(lines[i]); i+=1
            i+=1 # +
            qual_lines=[]
            qlen=0; slen=sum(len(s) for s in seq_lines)
            while i < len(lines) and qlen < slen:
                qual_lines.append(lines[i]); qlen+=len(lines[i]); i+=1
            seqs.append((name,"".join(seq_lines),"".join(qual_lines),desc))
        else: i+=1
    return seqs

def write_text_out(text, out_path):
    if out_path in (None,"-"):
        sys.stdout.write(text)
    else:
        # gz?
        if out_path.endswith(".gz") or out_path.endswith(".bgzf"):
            with open(out_path,'wb') as f: bgzf_write(f, text.encode(), level=1)
        else:
            with open(out_path,'w') as f: f.write(text)

def output_records(header, records, out_path, fmt, argv, no_pg=False, pg=True, level=6, uncompressed=False, sam_header=True):
    # fmt SAM/BAM/CRAM ; if out_path extension overrides if fmt None?
    hdr=list(header)
    if pg: add_pg(hdr, argv, no_pg=no_pg)
    if fmt=="BAM" or (fmt is None and out_path and (out_path.endswith(".bam"))):
        data=encode_bam(hdr, records)
        if out_path in (None,"-"):
            bgzf_write(sys.stdout.buffer, data, level=(0 if uncompressed else level))
        else:
            with open(out_path,'wb') as f: bgzf_write(f, data, level=(0 if uncompressed else level))
    elif fmt=="CRAM":
        eprint("samtools: CRAM output not supported in this implementation")
        raise SystemExit(1)
    else:
        # SAM
        lines=[]
        if sam_header:
            lines.extend(hdr)
        lines.extend(r.sam_line() for r in records)
        text="\n".join(lines)+("\n" if lines else "")
        if out_path in (None,"-"):
            # if stdout is tty? just write
            sys.stdout.buffer.write(text.encode())
