    # returns (name, start0, end0 exclusive or None)
    # chr, chr:pos, chr:start-end, chr:start..
    m=re.match(r'^(.+?):([\d,]+)-([\d,]*)$', reg)
    if m:
        name=m.group(1); s=int(m.group(2).replace(",",""))-1; e=int(m.group(3).replace(",","")) if m.group(3) else None
        return (name,s,e)
    m=re.match(r'^(.+?):([\d,]+)$', reg)
    if m:
        name=m.group(1); s=int(m.group(2).replace(",",""))-1
        return (name,s,None)
