def parse_region_str(reg):
    # returns (name, start0, end0 exclusive or None)
    # chr, chr:pos, chr:start-end, chr:start..
    m=re.match(r'^(.+?):([\d,]+)-([\d,]*)$', reg)
    if m:
        name=m.group(1); s=int(m.group(2).replace(",",""))-1; e=int(m.group(3).replace(",","")) if m.group(3) else None
        return (name,s,e)
    m=re.match(r'^(.+?):([\d,]+)$', reg)
    if m:
        name=m.group(1); s=int(m.group(2).replace(",",""))-1
        return (name,s,None)
    return (reg,0,None)

def rec_overlaps_region(r, region):
    name,s,e = region
    if r.rname != name: return False
    if r.pos==0: return False
    r_s=r.pos-1; r_e=ref_end(r.pos, r.ops())
    if r_e==r_s: r_e=r_s+1
    if e is not None and r_s >= e: return False
    if r_e <= s: return False
    return True

def read_bed(path):
    regs=[]
    with open(path) as f:
        for line in f:
            if not line.strip() or line.startswith("#") or line.startswith("track"): continue
            p=line.rstrip("\n").split("\t")
            if len(p)<3: p=line.split()
            try:
                regs.append((p[0], int(p[1]), int(p[2]), p))
            except: continue
    return regs

def natural_key(s):
    parts=re.split(r'(\d+)', s)
    key=[]
    for p in parts:
        if p.isdigit(): key.append((0,int(p), ""))
        else: key.append((1,0,p))
    return key

