import subprocess
orig=subprocess.check_output(["/workspace/executable","stats","/tmp/probe/toy.sam"],text=True)
gcc={}
for line in orig.splitlines():
    p=line.split('\t')
    if p[0]=='GCC': gcc[int(p[1])]=[float(x) for x in p[2:]]
recs=[]
for line in open('/tmp/probe/toy.sam'):
    if line.startswith('@'): continue
    f=line.split('\t'); recs.append((int(f[1]),f[9]))
COMP=str.maketrans("ACGT","TGCA")
def rc(s): return s.translate(COMP)[::-1]
def table(fn):
    maxl=max(len(s) for _,s in recs); out={}
    for cyc in range(1,maxl+1):
        cnt={'A':0,'C':0,'G':0,'T':0,'N':0,'O':0}
        for flag,s in recs:
            ss=fn(flag,s)
            if len(ss)>=cyc:
                b=ss[cyc-1].upper()
                cnt[b if b in cnt else 'O']+=1
        tot=cnt['A']+cnt['C']+cnt['G']+cnt['T']
        if tot: out[cyc]=[round(100*cnt[k]/tot,2) for k in 'ACGT']+[round(100*cnt['N']/tot,2),round(100*cnt['O']/tot,2)]
    return out
hyps={
 'stored': lambda f,s:s,
 'revcomp_rev': lambda f,s: rc(s) if f&16 else s,
 'reverse_rev': lambda f,s: s[::-1] if f&16 else s,
 'comp_rev': lambda f,s: s.translate(COMP) if f&16 else s,
 'revcomp_all_last?': lambda f,s: rc(s) if f&128 else s,
}
for name,fn in hyps.items():
    tab=table(fn)
    diffs=sum(1 for k in gcc if tab.get(k)!=gcc[k])
    print(name, "diff cycles", diffs, "of", len(gcc))
    if diffs<5:
        for k in gcc:
            if tab.get(k)!=gcc[k]: print(k,gcc[k],tab.get(k))
