import importlib.util, math
spec=importlib.util.spec_from_file_location("st","/workspace/samtools.py"); mod=importlib.util.module_from_spec(spec); spec.loader.exec_module(mod)
h,recs,fmt=mod.detect_and_read("/tmp/ex1_orig/ex1.bam")
from collections import defaultdict
by=defaultdict(list)
for r in recs: by[r.qname].append(r)
def st(vals):
    m=sum(vals)/len(vals); var=sum((x-m)**2 for x in vals)/len(vals); return len(vals),round(m,4),round(math.sqrt(var),4)
vals=[]; vals2=[]; diffs=[]
for q,grp in by.items():
    prim=[r for r in grp if not(r.flag&0x900)]
    if len(prim)!=2: continue
    a,b=prim
    span=max(mod.ref_end(a.pos,a.ops()), mod.ref_end(b.pos,b.ops())) - min(a.pos,b.pos) +1
    vals.append(span)
    # READ1's tlen abs
    r1=[r for r in prim if r.flag&0x40]
    if r1: 
        vals2.append(abs(r1[0].tlen))
        if span!=abs(r1[0].tlen): diffs.append((q,span,r1[0].tlen, a.pos,b.pos))
print('actual span',st(vals))
print('tlen',st(vals2))
print('diff examples',diffs[:10], len(diffs))
# candidate using READ1 record: distance from its pos to mate pos + mate seq len approximated by its own seq len
vals3=[]
for r in recs:
    if (r.flag&0x40) and r.tlen!=0:
        # template end estimation?
        if r.tlen>0: vals3.append(r.tlen)
        else: vals3.append(abs(r.tlen))
# maybe stats excludes outliers / uses -i max insert 8000 and -m most inserts 0.99: It reports average of main part (99%) trimming largest 1%? That would lower mean slightly.
vals_sorted=sorted(vals2)
for trim in [0.99,0.995]:
    n=int(len(vals_sorted)*trim); print('trim',trim, st(vals_sorted[:n]))
# maybe it uses insert sizes of pairs where both reads are first/last and counted from a record that is leftmost (positive tlen) but only if its flag is READ1? already
# Compute insert as pnext - pos + seq_len of READ1 (like distance between 5' ends + len)
vals4=[]
for r in recs:
    if (r.flag&0x40) and r.pnext:
        vals4.append(abs(r.pnext - r.pos) + len(r.seq))
