        for ln,op in m.parse_cigar(r.cigar):
            if op in "M=X": qp+=ln
            elif op=='I':
                c=cycle_rule(qp); ic.setdefault(c,[0,0,0,0])[1 if rev else 0]+=1; qp+=ln
            elif op=='D':
                ic.setdefault(qp,[0,0,0,0])[3 if rev else 2]+=1
            elif op=='S': qp+=ln
    return ic
