def x31(s, init=None):
    b=s.encode()
    if init is None:
        h=b[0] if b else 0
        for c in b[1:]: h=(h*31 + c) & 0xffffffff
        return h
    else:
        h=init
        for c in b: h=(h*31 + c) & 0xffffffff
        return h
