    h=0
    for c in s.encode(): h=(h*31+c)&0xffffffff
    return h
def fnv(s):
    h=2166136261
    for c in s.encode(): h=((h ^ c)*16777619)&0xffffffff
    return h
def crc(s): return binascii.crc32(s.encode()) & 0xffffffff
def md5_int(s): return int(hashlib.md5(s.encode()).hexdigest()[:8],16)
def djb(s):
    h=5381
    for c in s.encode(): h=((h*33)+c)&0xffffffff
    return h
def sdbm(s):
    h=0
    for c in s.encode(): h=(c + h*65599)&0xffffffff
    return h
hashes={"x31":x31,"x31_0":x31_0,"fnv":fnv,"crc":crc,"md5":md5_int,"djb":djb,"sdbm":sdbm}
combos={
