import hashlib, binascii
names=["r001","r002","r003","r004","x1","x2","x3","x4","x5","x6"]
obs={1: {"r001","r002","x2","x4","x5","x6"}, 42: {"r003","x1","x3","x5","x6"}, 0: {"r003","x2","x4","x6"}}
def x31(s):
    b=s.encode(); h=b[0] if b else 0
    for c in b[1:]: h=(h*31+c)&0xffffffff
    return h
def wang(h):
    h = ((h ^ 61) ^ (h >> 16)) & 0xffffffff
    h = (h + (h << 3)) & 0xffffffff
    h ^= h >> 4
    h = (h * 0x27d4eb2d) & 0xffffffff
    h ^= h >> 15
    return h
def wang2(h): # wang 64 to 32?
    h = (h ^ 61) ^ (h>>16); h=(h+(h<<3))&0xffffffff; h ^= h>>4; h=(h*0x27d4eb2d)&0xffffffff; h ^= h>>15; return h
def fmix(h):
    h ^= h>>16; h=(h*0x85ebca6b)&0xffffffff; h ^= h>>13; h=(h*0xc2b2ae35)&0xffffffff; h ^= h>>16; return h
def murmur2_final(h):
    # MurmurHash2 finalizer
    h ^= h>>13; h=(h*0x5bd1e995)&0xffffffff; h ^= h>>15; return h
finals={"wang":wang,"fmix":fmix,"murmur":murmur2_final, "identity":lambda h:h}
def check(desc,fn):
    for seed,exp in obs.items():
        sel={n for n in names if fn(n,seed)<0.5}
        if sel!=exp: return
    print("MATCH",desc)
for fname,ff in finals.items():
    for combname,comb in [('h+seed',lambda h,s:h+s),('h^seed',lambda h,s:h^s),('h+seed*2654435761',lambda h,s:h+s*2654435761),('seed+fmix?',lambda h,s:h+s)]:
        for modname,frac in [('top',lambda v:v/2**32),('%100',lambda v:(v%100)/100),('%1000',lambda v:(v%1000)/1000),('%10000',lambda v:(v%10000)/10000)]:
            check(f"{fname} {combname} {modname}", lambda n,s,ff=ff,comb=comb,frac=frac: frac(ff(comb(x31(n),s)&0xffffffff)))
        # also final on string hash with seed appended as string
    # end
# Hash could be of qname with seed salt string: e.g. hash31 starting with seed char?
for saltfmt in ["{s}{n}","{n}{s}"]:
    for modname,frac in [('top lambda',None)]:
        pass
    def make(saltfmt):
        return lambda n,s: (x31(saltfmt.format(s=s,n=n)))/2**32
    # x31 of formatted differs because x31 first char etc but our x31 function works for any string
    for fname in ['x31']:
        ok=True
        for seed,exp in obs.items():
            sel={n for n in names if (x31(saltfmt.format(s=seed,n=n)))/2**32 < 0.5}
            if sel!=exp: ok=False
        if ok: print("MATCH salt x31",saltfmt)
print("done")
for n in names: print(n, hex(wang(x31(n)+1)), hex(fmix(x31(n))))
