import hashlib, struct
names=["r001","r002","r003","r004","x1","x2","x3","x4","x5","x6"]
obs={1: {"r001","r002","x2","x4","x5","x6"}, 42: {"r003","x1","x3","x5","x6"}, 0: {"r003","x2","x4","x6"}}
def test(desc, fn):
    for seed,exp in obs.items():
        sel={n for n in names if fn(n,seed)<0.5}
        if sel!=exp: return
    print("MATCH",desc)
for alg in ['md5','sha1','sha256']:
  for fmt_bytes in ['n+seedLE','seedLE+n','n+seedBE','seedBE+n','n+seedbyte','seedbyte+n']:
    for endian in ['little','big']:
      for nbytes in [4,8]:
        def make(alg=alg,fmt_bytes=fmt_bytes,endian=endian,nbytes=nbytes):
            return lambda n,s: int.from_bytes(getattr(hashlib,alg)((n.encode()+struct.pack('<I',s)) if fmt_bytes=='n+seedLE' else (struct.pack('<I',s)+n.encode()) if fmt_bytes=='seedLE+n' else (n.encode()+struct.pack('>I',s)) if fmt_bytes=='n+seedBE' else (struct.pack('>I',s)+n.encode()) if fmt_bytes=='seedBE+n' else (n.encode()+bytes([s&255])) if fmt_bytes=='n+seedbyte' else (bytes([s&255])+n.encode())).digest()[:nbytes],endian)/(1<<(8*nbytes))
        test(f"{alg} {fmt_bytes} {endian} {nbytes}", make())
print("done")
