for fn in ["/tmp/cross/cross.bam.bai","/tmp/probe/toy.bam.bai"]:
    data=open(fn,'rb').read(); print(fn,len(data))
    off=4; n,=struct.unpack_from('<i',data,off); off+=4
    for r in range(n):
        nb,=struct.unpack_from('<i',data,off); off+=4; print(" ref",r,"nbin",nb)
        for b in range(nb):
            bin_,nc=struct.unpack_from('<Ii',data,off); off+=8; chunks=[]
            for c in range(nc): chunks.append(struct.unpack_from('<QQ',data,off)); off+=16
            print("   bin",bin_,chunks)
        ni,=struct.unpack_from('<i',data,off); off+=4; print("  nintv",ni)
        for i in range(ni): v,=struct.unpack_from('<Q',data,off); off+=8; print("    intv",i,hex(v))
    print(" trailing",data[off:])
