import subprocess, os, shutil
for exe,tag in [("/workspace/executable","orig"),("/tmp/testbin/executable","new")]:
    d=f"/tmp/readme_{tag}"
    if os.path.exists(d): shutil.rmtree(d)
    os.makedirs(d)
    for f in os.listdir("/tmp/probe"): 
        if f.startswith("ex1") or f.startswith("toy"): shutil.copy(f"/tmp/probe/{f}",d)
    def run(args, inp=None):
        p=subprocess.run([exe]+args,cwd=d,capture_output=True)
        print(tag,args,"rc",p.returncode,"out",len(p.stdout),"err",p.stderr[:100])
        return p
    run(["faidx","ex1.fa"])
    run(["view","-S","-b","-t","ex1.fa.fai","-o","ex1.bam","ex1.sam.gz"])
